before.content:
if ($LASTEXITCODE -ne 0) { throw "TypeScript reverse RPC conformance failed: $LASTEXITCODE" }
& node .\tooling\acp-conformance\run-acpx-smoke.mjs .\build\stage3-acpx.json
if ($LASTEXITCODE -ne 0) { throw "acpx interaction smoke failed: $LASTEXITCODE" }
& node .\tooling\acp-conformance\run-gold-band-smoke.mjs .\build\stage3-gold-band.json
if ($LASTEXITCODE -ne 0) { throw "Gold-Band interaction smoke failed: $LASTEXITCODE" }
& node .\scripts\verify-api-baseline.mjs

after.content:
if ($LASTEXITCODE -ne 0) { throw "TypeScript reverse RPC conformance failed: $LASTEXITCODE" }
& node .\tooling\acp-conformance\run-acpx-smoke.mjs .\build\stage3-acpx.json
if ($LASTEXITCODE -ne 0) { throw "acpx interaction smoke failed: $LASTEXITCODE" }
$priorCargoOffline = $env:CARGO_NET_OFFLINE
$env:CARGO_NET_OFFLINE = 'true'
& node .\tooling\acp-conformance\run-gold-band-smoke.mjs .\build\stage3-gold-band.json
$env:CARGO_NET_OFFLINE = $priorCargoOffline
if ($LASTEXITCODE -ne 0) { throw "Gold-Band interaction smoke failed: $LASTEXITCODE" }
& node .\scripts\verify-api-baseline.mjs
if ($LASTEXITCODE -ne 0) { throw "API baseline verification failed: $LASTEXITCODE" }
